import seed from '../data/seed.json'
import type { AppState, ChecklistItem, Criterion, DeptFile, Domain, Faculty } from '../types'

export const STATE_VERSION = 2

/** Fresh state built from src/data/seed.json (generated by scripts/build_seed.py). */
export function initialState(): AppState {
  // Cloned so callers can mutate it without touching the imported seed.
  return structuredClone({
    version: STATE_VERSION,
    academicYears: [seed.academicYear],
    domains: seed.domains as Domain[],
    files: seed.files as DeptFile[],
    items: seed.items as ChecklistItem[],
    faculty: seed.faculty as Faculty[],
    criteria: seed.criteria as Criterion[],
    statuses: {},
    activity: [],
  })
}

/** Brings saved state from an older version up to date without losing edits. */
export function migrate(saved: AppState): AppState | null {
  if (saved.version === STATE_VERSION) return saved
  if (saved.version === 1) {
    const fresh = initialState()
    return { ...saved, version: STATE_VERSION, faculty: fresh.faculty, criteria: fresh.criteria }
  }
  return null
}
